<?php
require __DIR__.'/../includes/functions.php';require_staff();$today=date('Y-m-d');$window=date('Y-m-d',strtotime('+7 days'));$q=db()->prepare("SELECT u.id,u.name,p.case_status,p.next_followup_date,p.followup_note FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE p.next_followup_date IS NOT NULL AND p.next_followup_date <= ? AND p.case_status NOT IN ('done','closed') ORDER BY p.next_followup_date ASC");$q->execute([$window]);$rows=$q->fetchAll();layout_start('تقویم پیگیری');?><div class="page-head"><div><p class="eyebrow">پیگیری پرونده‌ها</p><h1>تقویم پیگیری</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><div class="stats-grid"><div class="stat-card warning"><strong><?=count(array_filter($rows,fn($r)=>$r['next_followup_date']<$today))?></strong><span>عقب‌افتاده</span></div><div class="stat-card accent"><strong><?=count(array_filter($rows,fn($r)=>$r['next_followup_date']===$today))?></strong><span>امروز</span></div><div class="stat-card"><strong><?=count($rows)?></strong><span>تا ۷ روز آینده</span></div></div><div class="card table-wrap"><table><thead><tr><th>دانش‌آموز</th><th>تاریخ</th><th>وضعیت</th><th>یادداشت</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="<?=$r['next_followup_date']<$today?'urgent':''?>"><td><?=e($r['name'])?></td><td><?=e($r['next_followup_date'])?></td><td><?=e($r['case_status'])?></td><td><?=e($r['followup_note']??'')?></td><td><a href="<?=e(url('/admin/student.php?id='.$r['id']))?>">مشاهده پرونده</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">پیگیری نزدیکی وجود ندارد.</td></tr><?php endif;?></tbody></table></div><?php layout_end(); ?>
